function cheapestPasses(days: number[], costs: number[]): number {
  const spans = [1, 7, 30];
  const go = (i: number): number => {
    if (i >= days.length) return 0;
    let best = Infinity;
    for (let t = 0; t < 3; t++) {
      let j = i;
      while (j < days.length && days[j] < days[i] + spans[t]) j++;
      best = Math.min(best, costs[t] + go(j));
    }
    return best;
  };
  return go(0);
}

