function cheapestPasses(days: number[], costs: number[]): number {
  const n = days.length, spans = [1, 7, 30];
  const best = new Array(n + 1).fill(0);
  const ptr = [n, n, n]; // ptr[t]: first visit not covered by pass t bought on days[i]
  for (let i = n - 1; i >= 0; i--) {
    best[i] = Infinity;
    for (let t = 0; t < 3; t++) {
      let j = ptr[t];
      while (j - 1 > i && days[j - 1] >= days[i] + spans[t]) j--;
      ptr[t] = j;
      best[i] = Math.min(best[i], costs[t] + best[j]);
    }
  }
  return best[0];
}

